<?php
/**
 * /llms.txt, /llms-full.txt (index) and /llms-full/{n}.txt (100 products each) with content generated by FeedTrix:
 * GET {api}/shops/{store_key}/llms.txt, …/llms-full.txt, …/llms-full/{n}.txt
 *
 * A local copy in var/cache (lifetime set from FeedTrix, 1 day by default) protects against API delays.
 * FeedTrix removes it through controller=purge after every catalog change. The last valid version of /llms.txt
 * and the index is a backup when the API does not respond (not with an inactive subscription: HTTP 402 removes it).
 *
 * @author    FeedTrix
 * @copyright FeedTrix
 * @license   AFL-3.0
 */
if (!defined('_PS_VERSION_')) {
    exit;
}

class FeedTrixLlms
{
    /** @return string copy directory of the current shop */
    private static function dir()
    {
        return _PS_CACHE_DIR_ . 'feedtrix/';
    }

    private static function prefix()
    {
        return self::dir() . 'llms_' . (int) FeedTrix::context()->shop->id . '_';
    }

    /**
     * File name from the URL: llms => /llms.txt, full => index, full-N => file number N.
     *
     * @return string|null API path
     */
    public static function apiPath($file)
    {
        if ('llms' === $file) {
            return 'llms.txt';
        }
        if ('full' === $file) {
            return 'llms-full.txt';
        }
        if (preg_match('/^full-([1-9][0-9]{0,3})$/', (string) $file, $m)) {
            return 'llms-full/' . $m[1] . '.txt';
        }

        return null;
    }

    /** Removes local copies (FeedTrix changed the content); with $withBackup also the backups (store disconnected). */
    public static function purgeLocal($withBackup = false)
    {
        foreach (glob(self::prefix() . '*.' . ($withBackup ? '{txt,bak}' : 'txt'), GLOB_BRACE) ?: [] as $path) {
            @unlink($path);
        }
    }

    /**
     * @param bool $missing set to true when the file does not exist (e.g. /llms-full/9.txt with 3 files, inactive subscription)
     *
     * @return string|null content or null when FeedTrix is unavailable and there is no copy
     */
    public static function content($file, &$missing = false)
    {
        $missing = false;
        $path = self::apiPath($file);
        if (null === $path) {
            $missing = true;

            return null;
        }
        $copy = self::prefix() . $file . '.txt';
        $page = 0 === strpos($file, 'full-');
        $backup = $page ? null : self::prefix() . $file . '.bak'; // catalog files have no backup (large stores)

        if (is_file($copy) && time() - filemtime($copy) < FeedTrixSettings::llmsTtl()) {
            return (string) file_get_contents($copy);
        }

        $response = FeedTrixApi::request('GET', '/shops/' . rawurlencode(FeedTrixSettings::storeKey()) . '/' . $path, '', [], $page ? 15 : 5);
        if (200 === $response['status'] && '' !== $response['body']) {
            if (!is_dir(self::dir())) {
                @mkdir(self::dir(), 0775, true);
            }
            @file_put_contents($copy, $response['body']);
            if ($backup) {
                @file_put_contents($backup, $response['body']);
            }

            return $response['body'];
        }
        if (402 === $response['status']) { // FeedTrix subscription inactive: no file and no backup
            @unlink($copy);
            if ($backup) {
                @unlink($backup);
            }
            $missing = true;

            return null;
        }
        if (404 === $response['status'] && $page) {
            $missing = true;

            return null;
        }
        if ($backup && is_file($backup)) {
            // FeedTrix unavailable: backup, retry in a minute
            @copy($backup, $copy);
            @touch($copy, time() - FeedTrixSettings::llmsTtl() + 60);

            return (string) file_get_contents($backup);
        }

        return null;
    }
}
